inline ::flatbuffers::Offset<WXFGrid> CreateWXFGrid(
    ::flatbuffers::FlatBufferBuilder &_fbb,
    wxfGridKind KIND = wxfGridKind::RegularLatLon,
    double LAT0 = 0.0,
    double LON0 = 0.0,
    double DLAT = 0.0,
    double DLON = 0.0,
    uint32_t NLAT = 0,
    uint32_t NLON = 0,
    bool PERIODIC_LON = false) {
  WXFGridBuilder builder_(_fbb);
  builder_.add_DLON(DLON);
  builder_.add_DLAT(DLAT);
  builder_.add_LON0(LON0);
  builder_.add_LAT0(LAT0);
  builder_.add_NLON(NLON);
  builder_.add_NLAT(NLAT);
  builder_.add_PERIODIC_LON(PERIODIC_LON);
  builder_.add_KIND(KIND);
  return builder_.Finish();
}

