inline const WXF *GetWXF(const void *buf) {
  return ::flatbuffers::GetRoot<WXF>(buf);
}

inline const WXF *GetSizePrefixedWXF(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<WXF>(buf);
}

inline const char *WXFIdentifier() {
  return "$WXF";
}

inline bool WXFBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, WXFIdentifier());
}

inline bool SizePrefixedWXFBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, WXFIdentifier(), true);
}

template <bool B = false>
inline bool VerifyWXFBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<WXF>(WXFIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedWXFBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<WXF>(WXFIdentifier());
}

inline void FinishWXFBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<WXF> root) {
  fbb.Finish(root, WXFIdentifier());
}

inline void FinishSizePrefixedWXFBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<WXF> root) {
  fbb.FinishSizePrefixed(root, WXFIdentifier());
}

inline std::unique_ptr<WXFT> UnPackWXF(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<WXFT>(GetWXF(buf)->UnPack(res));
}

inline std::unique_ptr<WXFT> UnPackSizePrefixedWXF(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<WXFT>(GetSizePrefixedWXF(buf)->UnPack(res));
}

